solution:
def longest_well_formed(s: str) -> int:
    best, stack = 0, [-1]          # bottom: the index just before the current stretch
    for i, ch in enumerate(s):
        if ch == "(":
            stack.append(i)
        else:
            stack.pop()                # the matching "(", or the old left edge
            if stack:
                best = max(best, i - stack[-1])
            else:
                stack.append(i)        # unmatched ")": the next stretch starts after it
    return best

perf.naive:
def longest_well_formed(s: str) -> int:
    best = 0
    for i in range(len(s)):
        balance = 0
        for j in range(i, len(s)):
            balance += 1 if s[j] == '(' else -1
            if balance < 0:
                break
            if balance == 0:
                best = max(best, j - i + 1)
    return best
